const icons={bag:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d="M6 8h12l-1 12H7L6 8Z"/><path d="M9 9V6a3 3 0 0 1 6 0v3"/></svg>',heart:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.9-8.6a5.5 5.5 0 0 0-.1-7.8Z"/></svg>',search:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><circle cx="11" cy="11" r="6.5"/><path d="m16 16 4 4"/></svg>',menu:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d="M3 7h18M3 12h18M3 17h18"/></svg>',user:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><circle cx="12" cy="8" r="3.5"/><path d="M4.5 21a7.5 7.5 0 0 1 15 0"/></svg>'};
const products=[
{slug:'dark-monsoon',name:'Dark Monsoon',notes:'Rain • Earth • Oud',subtitle:'The Power After the Storm',description:'Deep, atmospheric and quietly commanding. Dark Monsoon captures the feeling of rain settling into the earth — where freshness meets depth and oud leaves behind a powerful, lingering presence.',mood:'Powerful',character:'Deep • Earthy • Mysterious',image:'/products/dark Monsoon.png',accent:'#afb7a8',price:1499},
{slug:'royal-zafran-rose',name:'Royal Zafran Rose',notes:'Saffron • Rose • Agarwood',subtitle:'A Rose, Made Royal.',description:'An opulent interpretation of timeless rose, enriched with the warmth of zafran and the depth of agarwood. Rich, elegant and unmistakably regal.',mood:'Regal',character:'Rich • Floral • Opulent',image:'/products/royal zefran rose.png',accent:'#c8aca2',price:1499},
{slug:'golden-ritual',name:'Golden Ritual',notes:'Coffee • Vanilla • Amber',subtitle:'Warmth Becomes a Ritual.',description:'The comforting richness of coffee meets smooth vanilla and glowing amber. Warm, enveloping and intimate — a fragrance inspired by the rituals we return to again and again.',mood:'Comforting',character:'Warm • Sweet • Intimate',image:'/products/golden ritual.png',accent:'#c8aa72',price:1499},
{slug:'golden-leaf',name:'Golden Leaf',notes:'Tobacco • Honey • Tonka',subtitle:'Wrapped in Golden Warmth.',description:'A rich tobacco accord softened by honey and the smooth warmth of tonka. Confident and refined, Golden Leaf leaves a warm impression that stays close to the skin.',mood:'Bold',character:'Warm • Refined • Confident',image:'/products/golden leaf.png',accent:'#b89a5e',price:1499},
{slug:'crystal-bloom',name:'Crystal Bloom',notes:'Water • Aromatic Air • Florals',subtitle:'Where Water Becomes a Flower.',description:'Clean, luminous and effortlessly fresh. Crystal Bloom evokes clear water, open air and delicate flowers awakening in the first light of morning.',mood:'Fresh',character:'Clean • Luminous • Airy',image:'/products/crystal bloom.png',accent:'#b4cdd1',price:1499},
{slug:'flora-silk',name:'Flora Silk',notes:'Soft Florals • Elegant Bouquet',subtitle:'Flowers, Draped in Silk.',description:'A graceful bouquet inspired by the softness of petals against silk. Delicate yet memorable, Flora Silk expresses understated elegance through a beautifully composed floral character.',mood:'Elegant',character:'Soft • Floral • Graceful',image:'/products/flora silk.png',accent:'#cfbdc6',price:1499}];
const reviews={'dark-monsoon':[{name:'Arjun M.',rating:5,date:'Aug 2026',text:'Opens with a rush of something dark and wet — like stepping into a forest after heavy rain. By the drydown it\'s all oud and warm earth. Wore it to a dinner party and my friend asked me three times what I was wearing.',verified:true},{name:'Priya K.',rating:5,date:'Jul 2026',text:'Not for the faint-hearted. This one announces you before you enter a room. I save it for evenings when I want to feel commanding.',verified:true},{name:'Vikram S.',rating:4,date:'Jul 2026',text:'The longevity is insane. Sprayed it on my kurta before a wedding and could still smell traces of it two days later.',verified:true},{name:'Meera R.',rating:5,date:'Jun 2026',text:'My husband rarely notices fragrances but this one stopped him mid-conversation. He actually borrowed it the next day.',verified:true},{name:'Rahul D.',rating:4,date:'Jun 2026',text:'Beautiful blend but needs a couple of hours to settle. The opening is a bit sharp, but once it calms down, it\'s magnificent.',verified:false}],'royal-zafran-rose':[{name:'Ananya S.',rating:5,date:'Aug 2026',text:'This is what I imagine a Mughal garden smells like at sunset. The saffron gives it a warmth that elevates the rose beyond anything I\'ve tried.',verified:true},{name:'Kavya P.',rating:5,date:'Jul 2026',text:'Bought this for my mother\'s birthday. She called me in tears — said it reminded her of her grandmother\'s home. That\'s the kind of fragrance this is.',verified:true},{name:'Deepak J.',rating:4,date:'Jul 2026',text:'Elegant without being old-fashioned. I wore it to an art gallery opening and felt perfectly dressed.',verified:true},{name:'Ritu M.',rating:5,date:'Jun 2026',text:'The rose here isn\'t sweet or powdery — it\'s regal and complex. You can feel the saffron weaving through it like a gold thread.',verified:true},{name:'Nikhil B.',rating:4,date:'May 2026',text:'A bit too floral for casual wear. But for weddings, celebrations, evenings out — absolutely perfect.',verified:false}],'golden-ritual':[{name:'Shreya T.',rating:5,date:'Aug 2026',text:'This is my comfort fragrance. Coffee and vanilla without smelling like a dessert — it\'s warm and sophisticated. My morning ritual now starts with two sprays.',verified:true},{name:'Aman G.',rating:5,date:'Jul 2026',text:'Reminds me of Sunday mornings with filter coffee and old songs. Not trying to be loud, just quietly beautiful.',verified:true},{name:'Rohan K.',rating:5,date:'Jul 2026',text:'My girlfriend stole my bottle after trying it once. Had to order another one for myself. Take that as the highest compliment.',verified:true},{name:'Pooja N.',rating:4,date:'Jun 2026',text:'Perfect winter fragrance. The amber base keeps it grounded while the vanilla gives it just enough sweetness.',verified:true},{name:'Aditya V.',rating:4,date:'May 2026',text:'Wore it on a first date. Three dates later, she said she fell in love with the scent before she fell in love with me.',verified:false}],'golden-leaf':[{name:'Sanjay R.',rating:5,date:'Aug 2026',text:'The tobacco note here is nothing like cigarette smoke — it\'s smooth, almost leathery. Combined with the honey, it creates something truly distinctive.',verified:true},{name:'Ishaan M.',rating:5,date:'Jul 2026',text:'I keep reaching for this one when I need confidence. Job interviews, presentations, important meetings — Golden Leaf is my silent partner.',verified:true},{name:'Tara L.',rating:4,date:'Jun 2026',text:'Sophisticated without being stuffy. My colleagues keep asking what I\'m wearing and I keep dodging the question.',verified:true},{name:'Karthik S.',rating:5,date:'Jun 2026',text:'The drydown is extraordinary — warm tonka and a hint of something resinous that stays close to skin.',verified:true},{name:'Nandini D.',rating:4,date:'May 2026',text:'Slightly masculine-leaning but I wear it confidently as a woman. The honey softens everything beautifully.',verified:false}],'crystal-bloom':[{name:'Anita W.',rating:5,date:'Aug 2026',text:'Opens slightly fresh on my skin and settles into a very soft floral scent. I wore it to dinner and could still smell it on my clothes the next morning.',verified:true},{name:'Raj P.',rating:4,date:'Jul 2026',text:'This is the fragrance equivalent of stepping out of a shower into a garden. Clean but alive.',verified:true},{name:'Sonal K.',rating:5,date:'Jul 2026',text:'Perfect for Indian summers when everything else feels too heavy. Crystal Bloom breathes.',verified:true},{name:'Aarav M.',rating:4,date:'Jun 2026',text:'My go-to for office wear. Professional without being boring, fresh without being generic.',verified:true},{name:'Divya S.',rating:5,date:'May 2026',text:'Subtler than the other Sixth Ritu fragrances but that\'s its strength. People lean in closer — which is exactly the point.',verified:false}],'flora-silk':[{name:'Meghna J.',rating:5,date:'Aug 2026',text:'Like wearing a silk dupatta made of flowers. This fragrance drapes rather than projects, and that elegance is what makes it special.',verified:true},{name:'Farah A.',rating:5,date:'Jul 2026',text:'Bought this sight unseen based on the description and wasn\'t disappointed. Delicate but present — you notice it the way you notice someone graceful entering a room.',verified:true},{name:'Priyanka S.',rating:4,date:'Jun 2026',text:'I\'ve been searching for a fragrance that feels feminine without being sweet. Flora Silk is exactly that.',verified:true},{name:'Ankit R.',rating:4,date:'Jun 2026',text:'Applied it before a long flight. Eight hours later, a flight attendant complimented me on it. The lasting power surprised me given how light it feels.',verified:true},{name:'Sunita V.',rating:5,date:'May 2026',text:'My mother says it smells like the jasmines she grew up with, but more refined. I think that\'s the perfect description.',verified:false}]};
const route=location.pathname.replace(/\/index\.html$/,'').replace(/\/$/,'')||'/';const app=document.querySelector('#app');let cart=JSON.parse(localStorage.getItem('tsr-cart')||'[]');let wishes=JSON.parse(localStorage.getItem('tsr-wishes')||'[]');let activeMood=0;let slide=0;let heroPaused=false;
const link=(path,label,cls='')=>`<a class="${cls}" href="${path}" data-link>${label}</a>`;const bySlug=s=>products.find(p=>p.slug===s);const money=()=>'';const persist=()=>{localStorage.setItem('tsr-cart',JSON.stringify(cart));localStorage.setItem('tsr-wishes',JSON.stringify(wishes));};
function header(){return `<div class="announcement"><span>Discover The Sixth Ritu — A New Season of Fine Fragrance</span></div><header class="header"><button class="icon-btn mobile-menu" data-menu aria-label="Open menu">${icons.menu}</button><a class="brand" href="/" data-link><img src="/logo.png" alt="The Sixth Ritu" /></a><nav class="nav" aria-label="Primary navigation">${link('/','Home')}${link('/shop','Shop')}${link('/collection','The Collection')}${link('/about','Our Story')}${link('/the-sixth-ritu','The Sixth Ritu')}${link('/contact','Contact')}</nav><div class="tools"><button class="icon-btn" data-search aria-label="Search">${icons.search}</button>${link('/account',icons.user,'icon-btn')}<button class="icon-btn" data-wishlist aria-label="Wishlist">${icons.heart}</button><button class="icon-btn" data-cart aria-label="Bag">${icons.bag}<span class="count">${cart.reduce((a,i)=>a+i.qty,0)}</span></button></div></header><div class="menu-panel" id="menu"><button class="icon-btn close-menu" data-menu aria-label="Close menu">×</button><a class="brand" href="/" data-link><img src="/logo.png" alt="The Sixth Ritu" /></a><nav>${link('/','Home')}${link('/shop','Shop')}${link('/collection','The Collection')}${link('/about','Our Story')}${link('/the-sixth-ritu','The Sixth Ritu')}${link('/contact','Contact')}${link('/wishlist','Wishlist')}${link('/cart','Bag')}</nav></div>`}
function footer(){return `<section class="newsletter section"><div class="container newsletter-grid"><div><p class="eyebrow">Enter the world of The Sixth Ritu</p><h2 class="display">Stay in the Season.</h2></div><div><p>Be the first to discover new creations, private releases and stories from The Sixth Ritu.</p><form class="email-form" data-newsletter><input aria-label="Your email address" type="email" placeholder="Your Email Address" required/><button>Join →</button></form><p class="form-note">By subscribing, you agree to receive communications from The Sixth Ritu.</p></div></div></section><footer class="footer"><div class="container"><div class="footer-top"><div class="footer-brand"><img src="/logo.png" alt="The Sixth Ritu"/><p>Fragrances inspired by emotion, created to become memory.</p></div><div><h3>Shop</h3>${products.map(p=>link('/product/'+p.slug,p.name)).join('')}</div><div><h3>Discover</h3>${link('/about','Our Story')}${link('/the-sixth-ritu','The Sixth Ritu')}${link('/collection','Our Philosophy')}${link('/contact','Contact Us')}</div><div><h3>Customer Care</h3>${link('/shipping','Shipping & Delivery')}${link('/returns','Returns & Exchanges')}${link('/faq','FAQs')}${link('/track-order','Track Order')}</div></div><div class="footer-bottom"><span>© 2026 The Sixth Ritu. All Rights Reserved.</span><span>${link('/privacy','Privacy')} &nbsp; ${link('/terms','Terms')}</span></div></div></footer>`}
function productCard(p){return `<article class="product-card"><button class="card-wish ${wishes.includes(p.slug)?'active':''}" data-wish="${p.slug}" aria-label="Save ${p.name}">${icons.heart}</button><a class="product-image" href="/product/${p.slug}" data-link><img src="${p.image}" alt="${p.name} fragrance" loading="lazy"/></a><div class="product-info"><div class="product-info-row"><div><h3>${p.name}</h3><p>${p.character}</p></div></div><p>Extrait de Parfum • 50 ML</p><div class="card-actions"><button data-add="${p.slug}">Add to Bag</button><button data-quick="${p.slug}">Quick View</button></div></div></article>`}
function home(){let p=products[0];return `<main id="main"><section class="hero" aria-label="The Sixth Ritu introduction">${[0,1,2].map((i)=>{let hp=products[[0,1,4][i]];let copy=[['THE SIXTH RITU','A Season Beyond the Six.','India has always known six seasons. We created one more — a season experienced through scent.','Discover The Collection','/collection','Our Story','/about'],['THE COLLECTION','Six Fragrances. Six Stories.','From rain-soaked earth and royal rose to golden amber and delicate florals, discover moments that remain with you.','Explore All Fragrances','/shop','',''],['FINE FRAGRANCE • INDIAN IMAGINATION • MODERN LUXURY','Made to Be Remembered.','Not simply a fragrance you wear, but a feeling that becomes part of your story.','Find Your Ritu','#find','','']][i];return `<div class="hero-slide ${i===0?'active':''}"><div class="hero-copy"><p class="eyebrow">${copy[0]}</p><h1 class="display">${copy[1]}</h1><p>${copy[2]}</p><div class="hero-actions">${link(copy[4],copy[3],'btn')}${copy[6]?link(copy[6],copy[5],'btn btn-light'):''}</div></div><div class="hero-product"><img src="${hp.image}" alt="${hp.name} fragrance" /></div></div>`}).join('')}<div class="hero-ui"><div class="dots">${[0,1,2].map(i=>`<button class="dot ${i===0?'active':''}" data-slide="${i}" aria-label="Show slide ${i+1}"></button>`).join('')}</div><div class="hero-arrows"><button data-slide-prev aria-label="Previous slide">←</button><button data-slide-next aria-label="Next slide">→</button></div></div></section><section class="section"><div class="container intro"><div><p class="eyebrow">Welcome to The Sixth Ritu</p><h2 class="display">Some Seasons Change the World.<br/>Others Stay With You.</h2></div><div class="intro-body"><p>India has always known six seasons — Vasanta, Grishma, Varsha, Sharad, Hemanta and Shishira. Each transforms the world around us and leaves behind a feeling.</p><p>We imagine another. A season found in the scent of rain after a storm, the warmth of an evening ritual, flowers resting on silk, or the memory of someone after they have gone.</p>${link('/about','Discover Our Story','text-link')}</div></div></section><section class="signature section"><div class="container"><div class="section-head"><div><p class="eyebrow">The Signature Collection</p><h2 class="display">Discover Your Ritu.</h2></div><p>Six distinctive fragrances. Six different moods. Created for the moments you want to remember.</p></div><div class="feature-rail" id="feature"><div class="feature-image"><img src="${p.image}" alt="${p.name} fragrance"/></div><div class="feature-details"><span class="feature-no">01 — 06</span><p class="notes">${p.notes}</p><h3 class="display">${p.name}</h3><h4>${p.subtitle}</h4><p>${p.description}</p>${link('/product/'+p.slug,'Explore '+p.name,'text-link')}<div class="rail-nav">${products.map((x,i)=>`<button class="${i===0?'active':''}" data-feature="${i}">${String(i+1).padStart(2,'0')}</button>`).join('')}</div></div></div></div></section><section class="mood" id="find"><div class="container mood-grid"><div class="mood-copy"><p class="eyebrow">Choose by Mood</p><h2 class="display">What Is Your Ritu Today?</h2><p>I want something...</p><div class="mood-list">${products.map((p,i)=>`<button class="mood-choice ${i===0?'active':''}" data-mood="${i}">${p.mood}</button>`).join('')}</div></div><div class="mood-visual"><img src="${p.image}" alt="${p.name} fragrance"/><div class="mood-caption"><h3>${p.name}</h3><p>${p.character}</p></div></div></div></section><section class="seasons"><div class="seasons-content"><p class="eyebrow">The Inspiration</p><h2 class="display">India Knows<br/>Six Seasons.</h2><div class="season-list"><span>VASANTA<small>New Beginnings</small></span><span>GRISHMA<small>Heat & Radiance</small></span><span>VARSHA<small>Rain & Renewal</small></span><span>SHARAD<small>Clarity</small></span><span>HEMANTA<small>Golden Warmth</small></span><span>SHISHIRA<small>Stillness</small></span></div><p>And Then, There Is One More.</p><div class="seasons-final">THE SIXTH RITU</div><p>A season without a date. A season experienced through scent.</p>${link('/the-sixth-ritu','Discover The Sixth Ritu','text-link')}</div></section><section class="philosophy"><div class="philosophy-copy"><p class="eyebrow">Our Philosophy</p><h2 class="display">Made to Be Worn.<br/>Created to Be Remembered.</h2><p>Every fragrance begins with a feeling. We translate that feeling through scent — bringing together Indian imagination, expressive perfume ingredients and a contemporary approach to luxury.</p>${link('/the-sixth-ritu','Our Philosophy','text-link')}</div><div class="philosophy-art"><img src="${products[2].image}" alt="Golden Ritual fragrance" loading="lazy"/></div></section><section class="campaign"><div class="campaign-content"><p class="eyebrow">The Season of Luxury</p><h2 class="display">A Memory Has No Season.</h2>${link('/collection','Explore The Collection','btn')}</div></section><section class="section"><div class="container"><div class="section-head"><div><p class="eyebrow">Shop by Character</p><h2 class="display">Find a Fragrance That Feels Like You.</h2></div></div><div class="character-grid">${products.map(p=>`<a class="character" href="/product/${p.slug}" data-link><h3>${p.mood} &<br/>${p.character.split(' • ')[1]||'Memorable'}</h3><p>Explore ${p.name} →</p></a>`).join('')}</div></div></section><section class="section"><div class="container art"><div class="art-text"><p class="eyebrow">The Art of Fragrance</p><h2 class="display">More Than a Fragrance. A Personal Ritual.</h2><p>A fragrance becomes meaningful through the moments connected to it. A first impression. A familiar evening. A celebration. A journey. A person.</p></div><div class="art-quote">The Sixth Ritu is created for those moments — fragrances designed to become part of your presence and, eventually, part of your memory.</div></div></section><section class="section"><div class="container"><div class="section-head"><div><p class="eyebrow">The Collection</p><h2 class="display">Six expressions of one idea.</h2></div>${link('/shop','Shop All','text-link')}</div><div class="product-grid">${products.map(productCard).join('')}</div></div></section><section class="statement"><blockquote>“We do not create fragrances merely to be worn. We create them to be remembered.”</blockquote><cite>— The Sixth Ritu</cite></section><section class="section social"><div class="container"><div class="social-head"><div><p class="eyebrow">Follow the Season</p><h2 class="display">@TheSixthRitu</h2></div><a href="#newsletter" class="text-link">Follow Our Journey</a></div><div class="social-rack"><div class="social-piece"><img src="${products[1].image}" alt="Royal Zafran Rose" loading="lazy"/></div><div class="social-piece"><img src="${products[4].image}" alt="Crystal Bloom" loading="lazy"/></div><div class="social-piece"><img src="${products[5].image}" alt="Flora Silk" loading="lazy"/></div></div></div></section></main>`}
function pageHero(kicker,title,copy=''){return `<section class="page-hero"><div class="container"><p class="eyebrow">${kicker}</p><h1 class="display">${title}</h1>${copy?`<p>${copy}</p>`:''}</div></section>`}
function shop(){return `<main id="main">${pageHero('The Signature Collection','Discover Your Ritu.','Six distinctive fragrances. Six different moods. Created for the moments you want to remember.')}<section class="section"><div class="container"><div class="shop-toolbar"><span>${products.length} fragrances</span><label>Sort <select class="select" data-sort><option value="name">Collection order</option><option value="az">Name: A–Z</option></select></label></div><div class="product-grid" id="shop-grid">${products.map(productCard).join('')}</div></div></section></main>`}
function reviewSection(p){const pr=reviews[p.slug]||[];if(!pr.length)return '';const avg=(pr.reduce((a,r)=>a+r.rating,0)/pr.length).toFixed(1);const counts=[5,4,3,2,1].map(s=>pr.filter(r=>r.rating===s).length);return `<section class="rv" id="reviews-section"><div class="rv-top"><div class="rv-summary"><h2>Reviews</h2><span class="rv-avg">${avg}</span><div class="rv-avg-stars">${'★'.repeat(Math.round(avg))}${'☆'.repeat(5-Math.round(avg))}</div><p class="rv-avg-sub">${pr.length} review${pr.length>1?'s':''}</p></div><div class="rv-bars">${counts.map((c,i)=>`<div class="rv-bar"><span>${5-i}</span><div class="rv-bar-track"><div class="rv-bar-fill" style="width:${pr.length?Math.round(c/pr.length*100):0}%"></div></div><span>${c}</span></div>`).join('')}</div><div class="rv-cta"><p>Share your experience</p><button class="rv-write-btn" data-open-review-modal>Write a Review</button></div></div><div class="rv-controls"><select class="rv-sort" data-rv-sort><option value="newest">Newest First</option><option value="highest">Highest Rated</option><option value="lowest">Lowest Rated</option></select></div><div class="rv-grid" data-rv-grid>${pr.slice(0,4).map(r=>`<div class="rv-card"><div class="rv-card-stars">${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)}</div><p class="rv-card-text">${r.text}</p><div class="rv-card-meta"><span class="rv-card-author">${r.name}</span><span class="rv-card-date">${r.date}</span>${r.verified?'<span class="rv-card-verified">✓ Verified</span>':''}</div></div>`).join('')}</div>${pr.length>4?'<button class="rv-more" data-rv-more>Load More Reviews</button>':''}<div class="rv-backdrop" data-rv-backdrop></div><div class="rv-modal" data-rv-modal><button class="rv-modal-close" data-rv-modal-close>×</button><h3>Write a Review</h3><form data-rv-form><div class="rv-field"><label>Your Rating</label><div class="rv-star-input">${[1,2,3,4,5].map(s=>`<button type="button" data-rv-star="${s}">☆</button>`).join('')}</div></div><div class="rv-field"><label>Name</label><input type="text" data-rv-name required/></div><div class="rv-field"><label>Review Title</label><input type="text" data-rv-title required/></div><div class="rv-field"><label>Your Review</label><textarea rows="4" data-rv-text required></textarea></div><button type="submit" class="rv-submit">Submit Review</button></form></div></section>`}
function videoSection(){return ''}
function productPage(p){if(!p)return notFound();const seasonData={'crystal-bloom':{ritu:'Vasanta',season:'Spring'},'golden-ritual':{ritu:'Grishma',season:'Summer'},'dark-monsoon':{ritu:'Varsha',season:'Monsoon'},'flora-silk':{ritu:'Sharad',season:'Autumn'},'golden-leaf':{ritu:'Hemanta',season:'Pre-Winter'},'royal-zafran-rose':{ritu:'Shishira',season:'Winter'}};const s=seasonData[p.slug]||{ritu:'The Sixth',season:'Ritu'};const pr=reviews[p.slug]||[];const avg=pr.length?(pr.reduce((a,r)=>a+r.rating,0)/pr.length).toFixed(1):'0';const notesList=p.notes.split(' • ');const related=products.filter(x=>x.slug!==p.slug).slice(0,4);return `<main id="main" class="pdp"><div class="pdp-top"><div class="pdp-gallery"><div class="pdp-main-img" data-pdp-zoom><img src="${p.image}" alt="${p.name} fragrance bottle"/><button class="pdp-zoom-icon" aria-label="Zoom image"><svg viewBox="0 0 24 24"><circle cx="11" cy="11" r="6.5"/><path d="m16 16 4 4"/><path d="M11 8v6M8 11h6"/></svg></button></div></div><div class="pdp-info"><p class="pdp-crumb"><a href="/" data-link>Home</a> / <a href="/shop" data-link>Shop</a> / ${p.name}</p><h1 class="pdp-name">${p.name}</h1><p class="pdp-tagline">${p.subtitle}</p>${pr.length?`<div class="pdp-rating" data-scroll-reviews><span class="pdp-stars">${'★'.repeat(Math.round(avg))}${'☆'.repeat(5-Math.round(avg))}</span><span class="pdp-rating-num">${avg}</span><span class="pdp-rating-count">${pr.length} review${pr.length>1?'s':''}</span></div>`:''}<p class="pdp-desc">${p.description}</p><p class="pdp-price">₹${p.price.toLocaleString('en-IN')} <span class="pdp-gst">+ GST</span></p><p class="pdp-size">Extrait de Parfum · 50 ML</p><div class="pdp-meta"><div><span class="pdp-meta-label">Mood</span><p class="pdp-meta-val">${p.mood}</p></div><div><span class="pdp-meta-label">Character</span><p class="pdp-meta-val">${p.character}</p></div><div><span class="pdp-meta-label">Concentration</span><p class="pdp-meta-val">Extrait de Parfum</p></div><div><span class="pdp-meta-label">Size</span><p class="pdp-meta-val">50 ML</p></div></div><div class="pdp-purchase"><div class="pdp-qty"><button data-pdp-qty="-1" aria-label="Decrease quantity">−</button><span id="pdp-qty">1</span><button data-pdp-qty="1" aria-label="Increase quantity">+</button></div><button class="pdp-add-btn" data-add="${p.slug}" data-pdp-add>ADD TO BAG</button></div><div class="pdp-actions"><button class="pdp-wish-btn ${wishes.includes(p.slug)?'active':''}" data-wish="${p.slug}">${icons.heart} ${wishes.includes(p.slug)?'SAVED':'WISHLIST'}</button><button class="pdp-share-btn" data-pdp-share><svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor"><path d="M4 12v8a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-8"/><polyline points="16 6 12 2 8 6"/><line x1="12" y1="2" x2="12" y2="15"/></svg> SHARE</button><div class="pdp-share-pop" style="display:none" data-share-pop><button data-share-copy>Copy Link</button><a href="https://wa.me/?text=${encodeURIComponent(p.name+' by The Sixth Ritu')}" target="_blank" rel="noopener">WhatsApp</a><a href="mailto:?subject=${encodeURIComponent(p.name)}&body=${encodeURIComponent(p.subtitle)}" target="_blank">Email</a></div></div><div class="pdp-trust"><div class="pdp-trust-item"><svg viewBox="0 0 24 24"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/></svg><span>100% Authentic</span></div><div class="pdp-trust-item"><svg viewBox="0 0 24 24"><path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78L12 21.23l8.84-8.84a5.5 5.5 0 0 0 0-7.78z"/></svg><span>Crafted in India</span></div><div class="pdp-trust-item"><svg viewBox="0 0 24 24"><rect x="1" y="3" width="15" height="13"/><polygon points="23 7 16 12 16 2"/></svg><span>Free Shipping</span></div><div class="pdp-trust-item"><svg viewBox="0 0 24 24"><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"/><polyline points="22 4 12 14.01 9 11.01"/></svg><span>Premium Quality</span></div></div><div class="pdp-accordions"><div class="pdp-acc open"><button class="pdp-acc-head" data-pdp-acc>THE STORY<span class="pdp-acc-icon">+</span></button><div class="pdp-acc-body"><div class="pdp-acc-inner">${p.description}</div></div></div><div class="pdp-acc"><button class="pdp-acc-head" data-pdp-acc>THE CHARACTER<span class="pdp-acc-icon">+</span></button><div class="pdp-acc-body"><div class="pdp-acc-inner">${p.character}. A fragrance created for the moments you want to remember.</div></div></div><div class="pdp-acc"><button class="pdp-acc-head" data-pdp-acc>FRAGRANCE NOTES<span class="pdp-acc-icon">+</span></button><div class="pdp-acc-body"><div class="pdp-acc-inner">${p.notes}</div></div></div><div class="pdp-acc"><button class="pdp-acc-head" data-pdp-acc>HOW TO WEAR<span class="pdp-acc-icon">+</span></button><div class="pdp-acc-body"><div class="pdp-acc-inner">Apply to pulse points — wrists, neck, behind the ears. Let the fragrance become part of your own ritual.</div></div></div><div class="pdp-acc"><button class="pdp-acc-head" data-pdp-acc>SHIPPING<span class="pdp-acc-icon">+</span></button><div class="pdp-acc-body"><div class="pdp-acc-inner">Complimentary shipping across India. Orders are processed within 1–2 business days.</div></div></div></div></div></div><section class="pdp-ritu"><div class="pdp-ritu-wrap"><div class="pdp-ritu-img"><img src="${p.image}" alt="${p.name}"/></div><div><p class="pdp-ritu-kicker">THE RITU EXPERIENCE</p><p class="pdp-ritu-season">${s.ritu} — ${s.season}</p><h2>${p.name}</h2><div class="pdp-ritu-notes">${notesList.map(n=>`<span class="pdp-ritu-note">${n.trim()}</span>`).join('')}</div><p class="pdp-ritu-motto">“${p.subtitle}”</p></div></div></section>${reviewSection(p)}<section class="pdp-related"><div class="pdp-related-head"><p class="pdp-kicker">Explore More</p><h2>You May Also Like</h2></div><div class="pdp-related-grid">${related.map(r=>`<div class="pdp-rel-card"><div class="pdp-rel-card-img"><button class="card-wish ${wishes.includes(r.slug)?'active':''}" data-wish="${r.slug}" aria-label="Save ${r.name}">${icons.heart}</button><a href="/product/${r.slug}" data-link><img src="${r.image}" alt="${r.name}" loading="lazy"/></a></div><h3><a href="/product/${r.slug}" data-link>${r.name}</a></h3><p class="pdp-rel-card-char">${r.character}</p><p class="pdp-rel-card-price">₹${r.price.toLocaleString('en-IN')} <small>+GST</small></p></div>`).join('')}</div></section><div class="pdp-sticky" data-pdp-sticky><div><p class="pdp-sticky-name">${p.name}</p><p class="pdp-sticky-price">₹${p.price.toLocaleString('en-IN')} <small>+GST</small></p></div><button class="pdp-sticky-add" data-add="${p.slug}">ADD TO BAG</button></div></main>`}
function collection(){return `<main id="main">${pageHero('The Collection','Six fragrances. One unforgettable season.','Six expressions of one idea — luxury that stays with you.')}<section class="section"><div class="container intro"><div><p class="eyebrow">Six moments</p><h2 class="display">Each creation is a way of remembering.</h2></div><div class="intro-body"><p>From rain-soaked earth and royal rose to golden amber and delicate florals, every creation takes a feeling and gives it a form through fragrance.</p>${link('/shop','Explore the Collection','text-link')}</div></div></section><section class="section signature"><div class="container"><div class="product-grid">${products.map(productCard).join('')}</div></div></section></main>`}
function narrative(type){const content={about:['Our Story','A Season Beyond the Six','India has always known six seasons. Each transforms the world around us and leaves behind a feeling. The Sixth Ritu is the one we imagine — formed through fragrance, memory and the moments that stay with you.','Some Moments Pass. Others Become a Season of Their Own.'],ritu:['The Sixth Ritu','A season experienced through scent.','The Sixth Ritu is not a date on a calendar. It is rain after a storm, the warmth of a ritual, flowers resting on silk, or the memory of someone after they have gone.','Made to Be Worn. Created to Be Remembered.']}[type];return `<main id="main">${pageHero(content[0],content[1],content[2])}<section class="section"><div class="container info-layout"><div class="info-side">Indian imagination,<br/>contemporary fine fragrance.</div><div class="info-copy"><p class="eyebrow">Our Philosophy</p><h2>${content[3]}</h2><p>Every fragrance begins with a feeling. We translate that feeling through scent, bringing together expressive perfume ingredients and a modern approach to luxury. Each creation is designed to unfold gradually on the skin, revealing its character over time.</p><p>Like a season becoming a memory.</p></div></div></section><section class="seasons"><div class="seasons-content"><p class="eyebrow">The Inspiration</p><h2 class="display">Vasanta · Grishma<br/>Varsha · Sharad<br/>Hemanta · Shishira</h2><div class="seasons-final">THE SIXTH RITU</div><p>The Season of Luxury</p></div></section><section class="section"><div class="container"><div class="product-grid">${products.map(productCard).join('')}</div></div></section></main>`}
function contact(){return `<main id="main">${pageHero('Contact','Begin a conversation.','For enquiries, collection information or a note for our team.') }<section class="section"><div class="container contact-grid"><div><p class="eyebrow">Contact Us</p><h2 class="display" style="font-size:3rem;margin-top:0">We would love to hear from you.</h2><p>Share your details and our team will be in touch. Contact information will be added here once confirmed.</p></div><form data-contact novalidate><div class="field"><label for="name">Name</label><input id="name" required /></div><div class="field"><label for="email">Email</label><input id="email" type="email" required /></div><div class="field"><label for="phone">Phone</label><input id="phone" type="tel" /></div><div class="field"><label for="subject">Subject</label><input id="subject" required /></div><div class="field"><label for="message">Message</label><textarea id="message" required></textarea></div><p class="form-status" aria-live="polite"></p><button class="btn">Send Message</button></form></div></section></main>`}
function searchPage(){return `<main id="main">${pageHero('Search','Find your fragrance.')}<section class="section"><div class="container search-box"><input class="search-input" data-search-input placeholder="Search the collection" aria-label="Search the collection" autofocus/><div id="search-results" class="product-grid" style="margin-top:55px"></div></div></section></main>`}
function wishlistPage(){return `<main id="main">${pageHero('Wishlist','Your saved season.')}<section class="section"><div class="container" id="wishlist-page">${wishes.length?`<div class="product-grid">${wishes.map(bySlug).filter(Boolean).map(productCard).join('')}</div>`:empty('Your wishlist is waiting.','Explore the collection','/shop')}</div></section></main>`}
function empty(title,label,path){return `<div class="empty"><h3>${title}</h3><p>Keep the fragrances that speak to you close.</p>${link(path,label,'btn')}</div>`}
function cartPage(){return `<main id="main">${pageHero('Bag','Your Season.')}<section class="section"><div class="container" id="cart-page">${cartContent(true)}</div></section></main>`}
function cartContent(full=false){if(!cart.length)return empty('Your bag is waiting.','Explore the collection','/shop');const subtotal=cart.reduce((a,i)=>{const p=bySlug(i.slug);return a+(p?p.price*i.qty:0)},0);let rows=cart.map(i=>{let p=bySlug(i.slug);return `<div class="cart-item"><img src="${p.image}" alt="${p.name}"/><div><h3>${p.name}</h3><p class="cart-item-spec">Extrait de Parfum · 50 ML</p><p class="cart-item-price">₹${p.price.toLocaleString('en-IN')} <small>+GST</small></p><div class="cart-item-bottom"><div class="qty"><button data-cart-qty="${p.slug}" data-change="-1">−</button><span>${i.qty}</span><button data-cart-qty="${p.slug}" data-change="1">+</button></div><button class="remove" data-remove="${p.slug}">Remove</button></div></div></div>`}).join('');return `${full?`<div style="max-width:740px">${rows}</div>`:rows}<div class="cart-total"><div class="total-row" style="font-size:1rem"><span>Subtotal</span><span>₹${subtotal.toLocaleString('en-IN')}</span></div><div class="total-row" style="font-size:.85rem;color:var(--muted,#716c62)"><span>GST (28%)</span><span>₹${Math.round(subtotal*0.28).toLocaleString('en-IN')}</span></div><div class="total-row"><span>Total</span><span>₹${Math.round(subtotal*1.28).toLocaleString('en-IN')}</span></div>${link('/checkout','Proceed to Checkout','btn')}</div>`}
function checkout(){const subtotal=cart.reduce((a,i)=>{const p=bySlug(i.slug);return a+(p?p.price*i.qty:0)},0);const gst=Math.round(subtotal*0.28);const total=subtotal+gst;const statesHtml='<option value="">Select State / UT</option>'+'Andhra Pradesh,Arunachal Pradesh,Assam,Bihar,Chhattisgarh,Goa,Gujarat,Haryana,Himachal Pradesh,Jharkhand,Karnataka,Kerala,Madhya Pradesh,Maharashtra,Manipur,Meghalaya,Mizoram,Nagaland,Odisha,Punjab,Rajasthan,Sikkim,Tamil Nadu,Telangana,Tripura,Uttar Pradesh,Uttarakhand,West Bengal,Andaman and Nicobar Islands,Chandigarh,Dadra and Nagar Haveli and Daman and Diu,Delhi,Jammu and Kashmir,Ladakh,Lakshadweep,Puducherry'.split(',').map(s=>`<option value="${s}">${s}</option>`).join('');const orderRows=cart.map(i=>{const p=bySlug(i.slug);return `<div style="display:flex;gap:12px;padding:12px 0;border-bottom:1px solid rgba(0,0,0,.06);align-items:center"><img src="${p.image}" alt="${p.name}" style="width:56px;height:68px;object-fit:contain;background:var(--v3-parchment,#f0ece3);padding:4px;flex-shrink:0"/><div style="flex:1;min-width:0"><p style="margin:0;font:400 .88rem/1.2 var(--v3-serif,var(--serif));">${p.name}</p><p style="margin:2px 0 0;font:400 .68rem/1 var(--v3-sans,var(--sans));color:var(--v3-ink-muted,var(--muted))">Qty: ${i.qty} · 50 ML</p></div><span style="font:500 .82rem/1 var(--v3-sans,var(--sans));white-space:nowrap">₹${(p.price*i.qty).toLocaleString('en-IN')}</span></div>`}).join('');return `<main id="main">${pageHero('Checkout','Complete your order.')}<section class="section"><div class="container checkout-grid"><form data-checkout novalidate><h2 class="display" style="font-size:2.4rem;margin-top:0">Contact</h2><div class="field"><label>Email Address</label><input type="email" name="email" required placeholder="you@example.com"/></div><div class="field"><label>Phone Number</label><input type="tel" name="phone" required placeholder="+91 98765 43210" pattern="[0-9+\\s\\-]{10,15}"/></div><h2 class="display" style="font-size:2.4rem;margin-top:28px">Shipping Address</h2><div class="field"><label>Full Name</label><input name="fullname" required placeholder="Your full name"/></div><div class="field"><label>Address Line 1</label><input name="address1" required placeholder="House/Flat No., Building, Street"/></div><div class="field"><label>Address Line 2 <small style="color:var(--muted,#716c62);text-transform:none;letter-spacing:0">(Optional)</small></label><input name="address2" placeholder="Landmark, Area"/></div><div style="display:grid;grid-template-columns:1fr 1fr;gap:16px"><div class="field"><label>Pincode</label><input name="pincode" required placeholder="e.g. 380001" pattern="[1-9][0-9]{5}" maxlength="6" data-pincode/></div><div class="field"><label>City</label><input name="city" required placeholder="City" data-city/></div></div><div class="field"><label>State / Union Territory</label><select name="state" required class="select" style="width:100%;padding:14px 0;border:0;border-bottom:1px solid var(--line,rgba(39,37,31,.17));background:transparent;outline:0;font-size:.88rem" data-state>${statesHtml}</select></div><p class="form-status" aria-live="polite"></p><button class="btn" style="width:100%;margin-top:12px;justify-content:center">Place Order — ₹${total.toLocaleString('en-IN')}</button><p style="text-align:center;font:400 .65rem/1.4 var(--v3-sans,var(--sans));color:var(--muted,#716c62);margin-top:12px">🔒 Secure checkout · All prices include applicable GST</p></form><aside class="order-summary"><h2>Order Summary</h2>${cart.length?`${orderRows}<div style="padding-top:14px"><div style="display:flex;justify-content:space-between;margin-bottom:6px;font:400 .82rem/1.4 var(--v3-sans,var(--sans));color:var(--v3-ink-body,var(--muted))"><span>Subtotal</span><span>₹${subtotal.toLocaleString('en-IN')}</span></div><div style="display:flex;justify-content:space-between;margin-bottom:6px;font:400 .82rem/1.4 var(--v3-sans,var(--sans));color:var(--v3-ink-body,var(--muted))"><span>GST (28%)</span><span>₹${gst.toLocaleString('en-IN')}</span></div><div style="display:flex;justify-content:space-between;margin-bottom:6px;font:400 .82rem/1.4 var(--v3-sans,var(--sans));color:var(--v3-ink-body,var(--muted))"><span>Shipping</span><span style="color:var(--v3-gold,var(--gold))">Free</span></div><div style="display:flex;justify-content:space-between;padding-top:10px;margin-top:8px;border-top:1px solid rgba(0,0,0,.08);font:500 1.1rem/1 var(--v3-serif,var(--serif))"><span>Total</span><span>₹${total.toLocaleString('en-IN')}</span></div></div>`:'<p>Your bag is empty. Add a fragrance before continuing.</p>'}<p class="form-note" style="margin-top:16px">Free shipping across India. Payment confirmation will follow once the payment gateway is connected.</p></aside></div></section></main>`}
function account(){return `<main id="main">${pageHero('Account','Your Sixth Ritu.')}<section class="section"><div class="container"><div class="account-card"><h2 class="display" style="font-size:3rem;margin-top:0">Welcome.</h2><p>Sign-in and order history will be connected when the customer account service is ready.</p>${link('/account/orders','View order history','text-link')}</div></div></section></main>`}
function supportPage(title,copy){return `<main id="main">${pageHero('Customer Care',title,copy)}<section class="section"><div class="container info-layout"><div class="info-side">The details,<br/>considered.</div><div class="info-copy"><p>This page is ready for your confirmed customer-care information. We have intentionally not made unverified shipping, return, privacy, or terms promises.</p><p>For assistance with an order, please use the contact form while the service contact information is being finalised.</p>${link('/contact','Contact Us','text-link')}</div></div></section></main>`}
function faq(){return `<main id="main">${pageHero('Customer Care','Frequently Asked Questions.')}<section class="section"><div class="container"><div class="detail-accordions"><details open><summary>How can I choose a fragrance?</summary><p>Begin with the mood that feels closest to you, or explore our collection by character.</p></details><details><summary>Where can I find product information?</summary><p>Each product page shares the fragrance character, story and supplied notes.</p></details><details><summary>How can I contact the team?</summary><p>Use the contact form and the team will respond through the confirmed channel.</p></details></div></div></section></main>`}
function notFound(){return `<main id="main" class="not-found"><div><p class="eyebrow">The Season is elsewhere</p><h1>404</h1><h2 class="display" style="font-size:3rem">This page has passed into memory.</h2>${link('/','Return Home','btn')}</div></main>`}
const offers=['SPECIAL LAUNCH OFFER — UP TO 10% OFF','DISCOVER THE SIXTH RITU','EXCLUSIVE ONLINE OFFER','50 ML EXTRAIT DE PARFUM','THE SEASON OF LUXURY','COMPLIMENTARY SHIPPING ON SELECTED ORDERS'];
const banners=[
  {slug:'royal-zafran-rose',desktop:'/hero banner 1.png',mobile:'/hero banner mobile 1.png',label:'Royal Zafran Rose'},
  {slug:'dark-monsoon',desktop:'/hero banner 2.png',mobile:'/hero banner mobile 2.png',label:'Dark Monsoon'},
  {slug:'golden-ritual',desktop:'/hero banner 3.png',mobile:'/hero banner mobile 3.png',label:'Golden Ritual'},
  {slug:'flora-silk',desktop:'/hero banner 4.png',mobile:'/hero banner mobile 4.png',label:'Flora Silk'}
];
function headerV2(){return `<div class="announcement announce-v2"><span>${offers[1]} · ${offers[4]}</span></div><header class="header header-v2"><button class="icon-btn mobile-menu" data-menu aria-label="Open menu">${icons.menu}</button><nav class="nav nav-v2" aria-label="Primary navigation">${link('/','Home')}${link('/shop','Shop')}${link('/collection','The Collection')}${link('/about','Our Story')}${link('/the-sixth-ritu','The Sixth Ritu')}${link('/contact','Contact')}</nav><a class="brand brand-v2" href="/" data-link><img src="/logo.png" alt="The Sixth Ritu" /></a><div class="tools"><button class="icon-btn" data-search aria-label="Search">${icons.search}</button>${link('/account',icons.user,'icon-btn desktop-tool')}<button class="icon-btn desktop-tool" data-wishlist aria-label="Wishlist">${icons.heart}</button><button class="icon-btn" data-cart aria-label="Bag">${icons.bag}<span class="count">${cart.reduce((a,i)=>a+i.qty,0)}</span></button></div></header><div class="menu-panel menu-v2" id="menu"><button class="icon-btn close-menu" data-menu aria-label="Close menu">×</button><a class="brand" href="/" data-link><img src="/logo.png" alt="The Sixth Ritu" /></a><p class="eyebrow">The Season of Luxury</p><nav>${link('/','Home')}${link('/shop','Shop')}${link('/collection','The Collection')}${link('/about','Our Story')}${link('/the-sixth-ritu','The Sixth Ritu')}${link('/contact','Contact')}${link('/wishlist','Wishlist')}${link('/cart','Bag')}</nav><p class="menu-note">Six fragrances. Six moments. One unforgettable season.</p><div class="menu-social">Instagram&nbsp;&nbsp; Facebook&nbsp;&nbsp; YouTube</div></div>`}
const drawerIcons={home:'<svg viewBox="0 0 24 24"><path d="m3.5 10 8.5-7 8.5 7v10.5h-6v-6h-5v6h-6Z"/></svg>',shop:'<svg viewBox="0 0 24 24"><path d="M5 8h14l-1 13H6L5 8Z"/><path d="M8.5 9V6.5a3.5 3.5 0 0 1 7 0V9"/></svg>',collection:'<svg viewBox="0 0 24 24"><rect x="3" y="3" width="7" height="7"/><rect x="14" y="3" width="7" height="7"/><rect x="3" y="14" width="7" height="7"/><rect x="14" y="14" width="7" height="7"/></svg>',story:'<svg viewBox="0 0 24 24"><path d="M12 3c2.3 4.8 6.1 5.5 8.3 5.3-1 5.8-4.6 9.7-8.3 12.7C8.3 18 4.7 14.1 3.7 8.3 5.9 8.5 9.7 7.8 12 3Z"/><path d="M12 5v13M7 11c2 .4 3.7-.1 5-1.3 1.3 1.2 3 1.7 5 1.3"/></svg>',ritu:'<svg viewBox="0 0 24 24"><path d="M12 2 15 7l5-1-1 5 3 3-4 2 1 5-5-2-2 3-2-3-5 2 1-5-4-2 3-3-1-5 5 1Z"/><circle cx="12" cy="12" r="2"/></svg>',contact:'<svg viewBox="0 0 24 24"><path d="M4 14v-2a8 8 0 0 1 16 0v2"/><path d="M4 13h3v6H4a2 2 0 0 1-2-2v-2a2 2 0 0 1 2-2ZM20 13h-3v6h3a2 2 0 0 0 2-2v-2a2 2 0 0 0-2-2Z"/><path d="M17 20c0 1.1-1.8 2-4 2"/></svg>',heart:icons.heart,bag:icons.bag};
function drawerRow(path,label,icon){return `<a href="${path}" data-link class="lux-drawer-row"><span class="drawer-row-icon">${drawerIcons[icon]}</span><span>${label}</span><b>›</b></a>`}
function headerV3(){return `<div class="announcement announce-v2"><span>${offers[1]} · ${offers[4]}</span></div><header class="header header-v2"><button class="icon-btn mobile-menu" data-menu aria-label="Open menu" aria-expanded="false" aria-controls="lux-menu">${icons.menu}</button><nav class="nav nav-v2" aria-label="Primary navigation">${link('/','Home')}${link('/shop','Shop')}${link('/collection','The Collection')}${link('/about','Our Story')}${link('/the-sixth-ritu','The Sixth Ritu')}${link('/contact','Contact')}</nav><a class="brand brand-v2" href="/" data-link><img src="/logo.png" alt="The Sixth Ritu" /></a><div class="tools"><button class="icon-btn" data-search aria-label="Search">${icons.search}</button>${link('/account',icons.user,'icon-btn desktop-tool')}<button class="icon-btn desktop-tool" data-wishlist aria-label="Wishlist">${icons.heart}</button><button class="icon-btn" data-cart aria-label="Bag">${icons.bag}<span class="count">${cart.reduce((a,i)=>a+i.qty,0)}</span></button></div></header><aside class="menu-panel luxury-drawer" id="lux-menu" aria-label="Mobile navigation" aria-hidden="true"><div class="drawer-main"><div class="drawer-top"><div><img src="/logo.png" alt="The Sixth Ritu"/><p>THE SEASON OF LUXURY</p></div><button class="lux-close" data-menu-close aria-label="Close menu">×</button></div><div class="drawer-nav-label"><span>NAVIGATION</span><i></i></div><nav class="lux-drawer-nav">${drawerRow('/','Home','home')}${drawerRow('/shop','Shop','shop')}${drawerRow('/collection','The Collection','collection')}${drawerRow('/about','Our Story','story')}${drawerRow('/the-sixth-ritu','The Sixth Ritu','ritu')}${drawerRow('/contact','Contact','contact')}</nav><div class="drawer-secondary">${drawerRow('/wishlist','Wishlist','heart')}<button class="lux-drawer-row" data-drawer-bag><span class="drawer-row-icon">${drawerIcons.bag}</span><span>Bag <em>${cart.reduce((a,i)=>a+i.qty,0)}</em></span><b>›</b></button></div><div class="drawer-bottom"><p>MORE THAN A FRAGRANCE.<br/><strong>A HIGHER SEASON.</strong></p><div class="drawer-emblem"><i></i><span>✾</span><i></i></div><div class="drawer-social" role="group" aria-label="Social channels"><button data-social aria-label="Instagram">◎</button><button data-social aria-label="Facebook">f</button><button data-social aria-label="YouTube">▶</button><button data-social aria-label="Pinterest">p</button></div></div></div><div class="drawer-visual"><img src="/hero banner 3.png" alt="Golden Ritual fragrance scene"/><div class="drawer-visual-words">SCENTS <b>◇</b> MEMORIES <b>◇</b> RITUALS <b>◇</b> BEYOND<br/>SEASONS</div><div class="drawer-visual-line"></div><div class="drawer-visual-brand">THE SIXTH RITU<br/><span>THE SEASON<br/>OF LUXURY</span></div></div></aside>`}
function footerV2(){return `<section class="newsletter newsletter-v2 section" id="newsletter"><div class="container newsletter-v2-grid"><div class="newsletter-mark"><p class="eyebrow">Enter the world of The Sixth Ritu</p><h2 class="display">Stay in the Season.</h2></div><div class="newsletter-form"><p>Be the first to discover new creations, private releases and stories from The Sixth Ritu.</p><form class="email-form" data-newsletter><input aria-label="Your email address" type="email" placeholder="Your Email Address" required/><button>Join the Season →</button></form><p class="form-note">By subscribing, you agree to receive communications from The Sixth Ritu.</p></div></div></section><footer class="footer footer-v2"><div class="container"><div class="footer-brand-hero"><img src="/logo.png" alt="The Sixth Ritu"/><span>The Season of Luxury</span></div><div class="footer-top"><div class="footer-brand"><p>Fragrances inspired by emotion, created to become memory.</p></div><div class="footer-col" data-footer-col><h3 data-footer-toggle>Shop <span class="footer-chevron">›</span></h3><div class="footer-col-body">${products.map(p=>link('/product/'+p.slug,p.name)).join('')}</div></div><div class="footer-col" data-footer-col><h3 data-footer-toggle>Discover <span class="footer-chevron">›</span></h3><div class="footer-col-body">${link('/about','Our Story')}${link('/the-sixth-ritu','The Sixth Ritu')}${link('/collection','The Collection')}${link('/contact','Contact Us')}</div></div><div class="footer-col" data-footer-col><h3 data-footer-toggle>Customer Care <span class="footer-chevron">›</span></h3><div class="footer-col-body">${link('/shipping','Shipping & Delivery')}${link('/returns','Returns & Exchanges')}${link('/faq','FAQs')}${link('/track-order','Track Order')}</div></div></div><div class="footer-bottom"><span>© 2026 The Sixth Ritu. All Rights Reserved.</span><span>${link('/privacy','Privacy')} · ${link('/terms','Terms')} · Instagram</span></div></div></footer>`}
function newProductStage(){let p=products[0];return `<section class="collection-stage section" id="collection-stage" style="--stage:${p.accent}"><div class="container"><div class="stage-kicker"><p class="eyebrow">The Signature Collection</p><p>Six Fragrances. Six Stories.</p></div><div class="stage-layout"><div class="stage-copy"><span class="stage-number">01 / 06</span><p class="notes">${p.notes}</p><h2 class="display">${p.name}</h2><h3>${p.subtitle}</h3><p class="stage-description">${p.description}</p>${link('/product/'+p.slug,'Explore '+p.name,'text-link')}</div><div class="stage-product"><div class="stage-orbit"></div><img src="${p.image}" alt="${p.name} fragrance"/></div></div><div class="stage-nav">${products.map((x,i)=>`<button class="${i===0?'active':''}" data-stage="${i}"><span>${String(i+1).padStart(2,'0')}</span>${x.name}</button>`).join('')}</div></div></section>`}
function rituSelector(){let p=products[0];return `<section class="ritu-selector" id="find"><div class="container ritu-grid"><div class="ritu-list"><p class="eyebrow">Choose by Mood</p><h2 class="display">What Is Your<br/>Ritu Today?</h2><p class="ritu-prompt">I want something...</p>${products.map((x,i)=>`<button class="ritu-choice ${i===0?'active':''}" data-ritu="${i}"><span>${x.mood}</span><small>${x.character}</small></button>`).join('')}</div><div class="ritu-product"><div class="ritu-wash"></div><img src="${p.image}" alt="${p.name} fragrance"/><div class="ritu-caption"><p class="eyebrow">Your Ritu</p><h3>${p.name}</h3><p>${p.character}</p>${link('/product/'+p.slug,'Find Your Fragrance','inline-link')}</div></div></div></section>`}
function seasonsV2(){const seasons=[['VASANTA','New Beginnings'],['GRISHMA','Heat & Radiance'],['VARSHA','Rain & Renewal'],['SHARAD','Clarity'],['HEMANTA','Golden Warmth'],['SHISHIRA','Stillness']];return `<section class="seasons-v2"><div class="season-pin"><div class="season-head"><p class="eyebrow">The Inspiration</p><p>India Knows Six Seasons.</p></div><div class="season-steps">${seasons.map((s,i)=>`<article class="season-step ${i===0?'active':''}" data-season="${i}"><span>${String(i+1).padStart(2,'0')}</span><h2 class="display">${s[0]}</h2><p>${s[1]}</p></article>`).join('')}</div><div class="season-final-v2"><p>And Then, There Is One More.</p><h2 class="display">THE SIXTH RITU</h2><span>The Season of Luxury</span></div></div></section>`}
function homeV2(){return `<main id="main" class="page-enter"><section class="banner-hero" aria-label="Featured fragrances">${banners.map((b,i)=>`<a href="/product/${b.slug}" data-link class="banner-slide ${i===0?'active':''}" data-banner-slide="${i}" aria-label="Explore ${b.label}"><picture><source media="(max-width: 640px)" srcset="${b.mobile}"><img src="${b.desktop}" alt="${b.label} campaign" ${i===0?'fetchpriority="high"':''}/></picture></a>`).join('')}<div class="banner-controls"><button data-slide-prev aria-label="Previous campaign">←</button><div class="banner-dots">${banners.map((b,i)=>`<button class="${i===0?'active':''}" data-slide="${i}" aria-label="Show ${b.label}"></button>`).join('')}</div><button data-slide-next aria-label="Next campaign">→</button></div></section><section class="offer-marquee" aria-label="Current offers"><div class="marquee-track">${[...offers,...offers].map(o=>`<span>${o}</span><b>✦</b>`).join('')}</div></section><section class="journey-intro section"><div class="container journey-grid"><div class="journey-title reveal"><p class="eyebrow">Welcome to The Sixth Ritu</p><h2 class="display">Some Seasons Change the World. <i>Others Stay With You.</i></h2></div><div class="journey-image reveal"><img src="/hero banner 2.png" alt="Dark Monsoon campaign" loading="lazy"/></div><div class="journey-copy reveal"><p>India has always known six seasons — Vasanta, Grishma, Varsha, Sharad, Hemanta and Shishira. Each transforms the world around us and leaves behind a feeling.</p><p>We imagine another. A season found in the scent of rain after a storm, the warmth of an evening ritual, flowers resting on silk, or the memory of someone after they have gone.</p>${link('/about','Discover Our Story','text-link')}</div></div></section>${newProductStage()}${rituSelector()}${seasonsV2()}<section class="memory-campaign"><img src="/hero banner 4.png" alt="Flora Silk campaign" loading="lazy"/><div class="memory-copy"><p class="eyebrow">The Sixth Ritu</p><h2 class="display">A Memory Has No Season.</h2>${link('/collection','Explore The Collection','btn')}</div></section><section class="character-showcase section"><div class="container"><div class="section-head sr"><div><p class="eyebrow">Shop by Character</p><h2 class="display">Find a Fragrance That Feels Like You.</h2></div></div><div class="character-track sr-stagger sr">${products.map(p=>`<a href="/product/${p.slug}" data-link class="character-tile" style="--tile:${p.accent}"><img src="${p.image}" alt="${p.name}" loading="lazy"/><div><p>${p.character}</p><h3 class="display">${p.mood}</h3><span>Explore ${p.name} →</span></div></a>`).join('')}</div></div></section><section class="art-v2 section"><div class="container art-v2-grid"><div class="art-visual sr-scale sr"><img src="/hero banner 3.png" alt="Golden Ritual campaign" loading="lazy"/></div><div class="art-copy reveal sr-right sr"><p class="eyebrow">The Art of Fragrance</p><h2 class="display">More Than a Fragrance. A Personal Ritual.</h2><p>A fragrance becomes meaningful through the moments connected to it. A first impression. A familiar evening. A celebration. A journey. A person.</p><div class="art-words">MEMORY<br/>RITUAL<br/>SCENT</div></div></div></section><section class="product-carousel-section section"><div class="container"><div class="section-head sr"><div><p class="eyebrow">The Collection</p><h2 class="display">Six expressions of one idea.</h2></div>${link('/shop','Shop All','text-link')}</div></div><div class="carousel-viewport"><div class="carousel-track" id="product-carousel">${products.map((p,i)=>`<article class="carousel-card" style="--accent:${p.accent}"><button class="card-wish ${wishes.includes(p.slug)?'active':''}" data-wish="${p.slug}" aria-label="Save ${p.name}">${icons.heart}</button><a href="/product/${p.slug}" data-link class="carousel-card-link"><div class="carousel-card-img"><img src="${p.image}" alt="${p.name} fragrance" loading="lazy"/></div><div class="carousel-card-info"><p class="eyebrow">${p.notes}</p><h3>${p.name}</h3><p class="carousel-sub">${p.subtitle}</p><span class="carousel-cta">Explore →</span></div></a></article>`).join('')}</div></div><div class="carousel-arrows"><button class="carousel-arrow" data-carousel-prev aria-label="Previous">←</button><button class="carousel-arrow" data-carousel-next aria-label="Next">→</button></div></section><section class="quote-v2 sr sr-scale"><div class="quote-line"></div><blockquote>“We do not create fragrances merely to be worn.<br/>We create them to be remembered.”</blockquote><cite>— The Sixth Ritu</cite></section><section class="social-v2 section"><div class="container"><div class="social-v2-head sr"><div><p class="eyebrow">Follow the Season</p><h2 class="display">@TheSixthRitu</h2></div><a href="#newsletter" class="text-link">Follow Our Journey</a></div></div><div class="social-ticker">${[...products,...products].map(p=>`<div><img src="${p.image}" alt="${p.name}" loading="lazy"/><span>${p.name}</span></div>`).join('')}</div></section></main>`}
function homeV3(){const feat=products[0];const seasonMap=[{name:'Vasanta',sub:'Spring',desc:'New Beginnings',slug:'crystal-bloom'},{name:'Grishma',sub:'Summer',desc:'Heat & Radiance',slug:'golden-ritual'},{name:'Varsha',sub:'Monsoon',desc:'Rain & Renewal',slug:'dark-monsoon'},{name:'Sharad',sub:'Autumn',desc:'Clarity & Grace',slug:'flora-silk'},{name:'Hemanta',sub:'Pre-Winter',desc:'Golden Warmth',slug:'golden-leaf'},{name:'Shishira',sub:'Winter',desc:'Rich Stillness',slug:'royal-zafran-rose'}];const best=[products[0],products[1],products[2]];const journal=[{tag:'Craft',title:'The Art of Indian Perfumery',desc:'How ancient techniques meet modern luxury in every bottle.',img:'/hero banner 2.png'},{tag:'Ritual',title:'Creating Your Fragrance Ritual',desc:'Transform an everyday moment into something extraordinary.',img:'/hero banner 3.png'},{tag:'Season',title:'Why India Has Six Seasons',desc:'The ancient wisdom behind the Sixth Ritu philosophy.',img:'/hero banner 4.png'}];return `<main id="main" class="home-v3"><section class="v3-hero"><div class="v3-hero-media"><img class="v3-hero-poster" src="/hero banner 2.png" alt="The Sixth Ritu — luxury Indian perfumery"/></div><div class="v3-hero-grad"></div><div class="v3-hero-content"><p class="v3-hero-tag">THE SIXTH RITU</p><h1>Fragrance, Through<br/>the Seasons.</h1><p class="v3-hero-sub">Six seasons. Six moods. One olfactory journey through India.</p><div class="v3-hero-ctas">${link('/shop','Explore the Collection','v3-btn')}<a href="#find-ritu" class="v3-btn-ghost">Discover Your Ritu</a></div></div><div class="v3-scroll-hint">Scroll</div></section><section class="v3-strip"><div class="v3-strip-track">${[...Array(2)].map(()=>'<span>EAU DE PARFUM</span><b>✦</b><span>INDIAN IMAGINATION</span><b>✦</b><span>SIX SEASONS</span><b>✦</b><span>MODERN LUXURY</span><b>✦</b><span>CRAFTED IN INDIA</span><b>✦</b><span>MADE TO BE REMEMBERED</span><b>✦</b>').join('')}</div></section><section class="v3-ritus v3-sec"><div class="v3 v3-section-head v3-sr"><p class="v3-kicker">The Signature Collection</p><h2>Find Your Ritu.</h2><p>Six distinctive fragrances. Six different moods.</p></div><div class="v3-ritu-scroll">${products.map((p,i)=>`<div class="v3-ritu-card v3-sr" style="transition-delay:${i*0.08}s"><div class="v3-ritu-card-img"><button class="card-wish ${wishes.includes(p.slug)?'active':''}" data-wish="${p.slug}" aria-label="Save ${p.name}">${icons.heart}</button><a href="/product/${p.slug}" data-link><img src="${p.image}" alt="${p.name}" loading="lazy"/></a></div><div class="v3-ritu-card-body"><p class="v3-ritu-card-season">${p.mood}</p><h3><a href="/product/${p.slug}" data-link>${p.name}</a></h3><p class="v3-ritu-card-notes">${p.notes}</p><p class="v3-ritu-card-price">₹${p.price.toLocaleString('en-IN')} <small>+GST</small></p><a href="/product/${p.slug}" data-link class="v3-ritu-card-cta">Explore →</a></div></div>`).join('')}</div></section><section class="v3-editorial v3-sec"><div class="v3 v3-editorial-grid"><div class="v3-editorial-text v3-sr"><p class="v3-kicker">Welcome to The Sixth Ritu</p><h2 class="v3-heading">Some Seasons Change the World. <em>Others Stay With You.</em></h2><p class="v3-body">India has always known six seasons — Vasanta, Grishma, Varsha, Sharad, Hemanta and Shishira. Each transforms the world around us and leaves behind a feeling. We imagine another. A season found in the scent of rain after a storm, the warmth of an evening ritual, flowers resting on silk, or the memory of someone after they have gone.</p>${link('/about','Discover Our Story','v3-link')}</div><div class="v3-editorial-img v3-sr"><img src="/hero banner 2.png" alt="The Sixth Ritu editorial" loading="lazy"/></div></div></section><section class="v3-featured"><div class="v3-featured-bg"><img src="/hero banner 2.png" alt="" loading="lazy"/></div><div class="v3-featured-grad"></div><div class="v3 v3-featured-content v3-sr"><p class="v3-kicker">The Signature Ritu</p><h2>Dark Monsoon</h2><p class="v3-featured-sub">${feat.subtitle}</p><div class="v3-featured-meta"><div><span>Character</span>${feat.character}</div><div><span>Notes</span>${feat.notes}</div><div><span>Concentration</span>Extrait de Parfum</div></div><p class="v3-featured-desc">${feat.description}</p>${link('/product/'+feat.slug,'Explore Dark Monsoon','v3-btn')}</div><div class="v3-featured-product v3-sr"><img src="${feat.image}" alt="${feat.name}"/></div></section><section class="v3-moods v3-sec" id="find-ritu"><div class="v3 v3-moods-head v3-sr"><p class="v3-kicker">Discover by Mood</p><h2>What Is Your Ritu Today?</h2></div><div class="v3 v3-moods-grid">${products.map(p=>`<div class="v3-mood-tile v3-sr"><img src="${p.image}" alt="${p.name}" loading="lazy"/><a href="/product/${p.slug}" data-link class="v3-mood-tile-overlay"><h3>${p.mood}</h3><p>${p.name} · ${p.notes}</p></a></div>`).join('')}</div></section><section class="v3-quote v3-sr"><div class="v3"><blockquote>“We do not create fragrances merely to be worn. We create them to be remembered.”</blockquote><cite>— The Sixth Ritu</cite></div></section><section class="v3-craft v3-sec"><div class="v3 v3-craft-layout"><div class="v3-craft-text v3-sr"><p class="v3-kicker">The Art of Fragrance</p><h2 class="v3-heading">More Than a Fragrance. <em>A Personal Ritual.</em></h2><p class="v3-body">A fragrance becomes meaningful through the moments connected to it. A first impression. A familiar evening. A celebration. A journey. A person. The Sixth Ritu is created for those moments.</p>${link('/about','Our Craft','v3-link')}</div><div class="v3-craft-frame v3-sr"><img src="/hero banner 3.png" alt="The art of Indian perfumery" loading="lazy"/><div class="v3-craft-play"><div class="v3-craft-play-btn"></div></div></div></div></section><section class="v3-seasons v3-sec"><div class="v3 v3-seasons-head v3-sr"><p class="v3-kicker">The Inspiration</p><h2>India Knows Six Seasons.</h2></div><div class="v3"><div class="v3-seasons-list">${seasonMap.map((s,i)=>`<div class="v3-season-item ${i===0?'active':''}" data-v3-season="${i}"><span class="num">${String(i+1).padStart(2,'0')}</span><h3>${s.name}</h3><p>${s.desc}</p></div>`).join('')}</div><div class="v3-season-reveal v3-sr"><div class="v3-season-fragrance" id="v3-season-fragrance"><img src="${bySlug(seasonMap[0].slug).image}" alt="${bySlug(seasonMap[0].slug).name}"/><div class="v3-season-fragrance-info"><h4>${bySlug(seasonMap[0].slug).name}</h4><p>${bySlug(seasonMap[0].slug).description}</p><a href="/product/${seasonMap[0].slug}" data-link class="v3-link">Explore →</a></div></div></div><div class="v3-season-final v3-sr"><p>And Then, There Is One More.</p><h2 class="v3-heading">THE SIXTH RITU</h2></div></div></section><section class="v3-best v3-sec"><div class="v3"><div class="v3-best-head v3-sr"><div><p class="v3-kicker">Most Loved</p><h2>Bestsellers.</h2></div>${link('/shop','Shop All','v3-link')}</div><div class="v3-best-grid">${best.map(p=>`<div class="v3-prod-card v3-sr"><div class="v3-prod-card-img"><button class="card-wish ${wishes.includes(p.slug)?'active':''}" data-wish="${p.slug}" aria-label="Save ${p.name}">${icons.heart}</button><a href="/product/${p.slug}" data-link><img src="${p.image}" alt="${p.name}" loading="lazy"/></a></div><h3><a href="/product/${p.slug}" data-link>${p.name}</a></h3><p class="v3-prod-card-char">${p.character}</p><p class="v3-prod-card-spec">Extrait de Parfum · 50 ML</p><p class="v3-prod-card-price">₹${p.price.toLocaleString('en-IN')} <small>+GST</small></p><div class="v3-prod-card-actions"><button data-add="${p.slug}">Add to Bag</button><button data-quick="${p.slug}">Quick View</button></div></div>`).join('')}</div></div></section><section class="v3-philo v3-sec"><div class="v3"><div class="v3-sr" style="margin-bottom:clamp(28px,4vw,48px)"><p class="v3-kicker">Our Philosophy</p><h2 class="v3-heading">Made to Be Worn. <em>Created to Be Remembered.</em></h2></div><div class="v3-philo-grid"><div class="v3-philo-item v3-sr"><span class="num">01</span><h3>Indian Imagination</h3><p>Every fragrance begins with a feeling rooted in India’s seasons, landscapes and rituals.</p></div><div class="v3-philo-item v3-sr"><span class="num">02</span><h3>Expressive Ingredients</h3><p>We bring together the finest perfume ingredients, composed to unfold gradually on the skin.</p></div><div class="v3-philo-item v3-sr"><span class="num">03</span><h3>Contemporary Luxury</h3><p>Modern sensibilities meet timeless Indian aesthetic — luxury that feels natural, not performed.</p></div><div class="v3-philo-item v3-sr"><span class="num">04</span><h3>Memory & Ritual</h3><p>A fragrance becomes meaningful through the moments connected to it. We design for those moments.</p></div></div></div></section><section class="v3-journal v3-sec"><div class="v3"><div class="v3-journal-head v3-sr"><div><p class="v3-kicker">From the Journal</p><h2>Stories & Craft.</h2></div>${link('/about','Read More','v3-link')}</div><div class="v3-journal-grid">${journal.map(j=>`<a class="v3-journal-card v3-sr" href="/about" data-link><div class="v3-journal-card-img"><img src="${j.img}" alt="${j.title}" loading="lazy"/></div><span class="v3-journal-card-tag">${j.tag}</span><h3>${j.title}</h3><p>${j.desc}</p></a>`).join('')}</div></div></section><section class="v3-social"><div class="v3 v3-social-head v3-sr"><h2>@TheSixthRitu</h2><p>Follow our journey through the seasons.</p></div><div class="v3-social-row">${products.map(p=>`<div><img src="${p.image}" alt="${p.name}" loading="lazy"/></div>`).join('')}</div></section><section class="v3-news v3-sec"><div class="v3 v3-sr"><p class="v3-kicker" style="color:var(--v3-gold-light)">Enter the World of The Sixth Ritu</p><h2>Stay in the Season.</h2><p>Be the first to discover new creations, private releases and stories.</p><form class="v3-news-form" data-newsletter><input type="email" placeholder="Your Email Address" aria-label="Email address" required/><button type="submit">Join</button></form><p class="v3-news-note">By subscribing, you agree to receive communications from The Sixth Ritu.</p></div></section><footer class="v3-footer"><div class="v3 v3-footer-top"><div class="v3-footer-brand"><img src="/logo.png" alt="The Sixth Ritu"/><p>Fragrances inspired by emotion, created to become memory.</p></div><div class="footer-col" data-footer-col><h4 data-footer-toggle>Shop <span class="chev">›</span></h4><div class="footer-col-body">${products.map(p=>link('/product/'+p.slug,p.name)).join('')}</div></div><div class="footer-col" data-footer-col><h4 data-footer-toggle>Discover <span class="chev">›</span></h4><div class="footer-col-body">${link('/about','Our Story')}${link('/the-sixth-ritu','The Sixth Ritu')}${link('/collection','The Collection')}${link('/contact','Contact Us')}</div></div><div class="footer-col" data-footer-col><h4 data-footer-toggle>Customer Care <span class="chev">›</span></h4><div class="footer-col-body">${link('/shipping','Shipping & Delivery')}${link('/returns','Returns & Exchanges')}${link('/faq','FAQs')}${link('/track-order','Track Order')}</div></div></div><div class="v3 v3-footer-bottom"><span>© 2026 The Sixth Ritu. All Rights Reserved.</span><span>${link('/privacy','Privacy')} · ${link('/terms','Terms')}</span></div></footer></main>`}
function render(){let content;if(route==='/'||route==='/index.html')content=homeV3();else if(route==='/shop')content=shop();else if(route==='/collection')content=collection();else if(route==='/about')content=narrative('about');else if(route==='/the-sixth-ritu')content=narrative('ritu');else if(route==='/contact')content=contact();else if(route==='/search')content=searchPage();else if(route==='/wishlist')content=wishlistPage();else if(route==='/cart')content=cartPage();else if(route==='/checkout')content=checkout();else if(route==='/account'||route==='/account/orders'||route==='/track-order')content=route==='/track-order'?supportPage('Track your order.','Order tracking will appear here once the fulfillment service is connected.'):account();else if(route==='/faq')content=faq();else if(['/shipping','/returns','/privacy','/terms'].includes(route))content=supportPage(({ '/shipping':'Shipping & Delivery','/returns':'Returns & Exchanges','/privacy':'Privacy Policy','/terms':'Terms & Conditions'})[route],'Details will be added once confirmed by The Sixth Ritu.');else if(route.startsWith('/product/'))content=productPage(bySlug(route.split('/').pop()));else content=notFound();const _isHome=route==='/'||route==='/index.html';app.innerHTML=headerV2()+content+(_isHome?'':footerV2())+overlays();bind();if(route==='/search')updateSearch('');setupMotion();bindLuxuryDrawer();bindDesktopHeader();if(_isHome)setupV3Motion();if(route.startsWith('/product/'))setupPDP();if(route==='/checkout')setupCheckout();}
function overlays(){const count=cart.reduce((a,i)=>a+i.qty,0);const subtotal=cart.reduce((a,i)=>{const p=bySlug(i.slug);return a+(p?p.price*i.qty:0)},0);let drawerInner;if(!cart.length){drawerInner=`<div class="drawer-empty"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d="M6 8h12l-1 12H7L6 8Z"/><path d="M9 9V6a3 3 0 0 1 6 0v3"/></svg><h3>Your bag is empty</h3><p>Discover fragrances crafted for the moments you want to remember.</p><a href="/shop" data-link class="drawer-empty-btn">Explore Collection</a></div>`;}else{const inCart=cart.map(i=>i.slug);const recos=products.filter(x=>!inCart.includes(x.slug)).slice(0,2);const rows=cart.map(i=>{const p=bySlug(i.slug);return `<div class="cart-item"><img src="${p.image}" alt="${p.name}"/><div><h3>${p.name}</h3><p class="cart-item-spec">Extrait de Parfum · 50 ML</p><p class="cart-item-price">₹${p.price.toLocaleString('en-IN')} <small>+GST</small></p><div class="cart-item-bottom"><div class="qty"><button data-cart-qty="${p.slug}" data-change="-1">−</button><span>${i.qty}</span><button data-cart-qty="${p.slug}" data-change="1">+</button></div><button class="remove" data-remove="${p.slug}">Remove</button></div></div></div>`}).join('');const recoHtml=recos.length?`<div class="drawer-reco"><h4>Complete Your Ritual</h4><div class="drawer-reco-items">${recos.map(r=>`<div class="drawer-reco-card"><img src="${r.image}" alt="${r.name}"/><div><h5>${r.name}</h5><p>${r.notes}</p></div><button class="drawer-reco-add" data-add="${r.slug}">Add</button></div>`).join('')}</div></div>`:'';drawerInner=`<div class="drawer-items">${rows}${recoHtml}</div><div class="drawer-footer"><div class="drawer-row"><span>Subtotal</span><span>₹${subtotal.toLocaleString('en-IN')}</span></div><div class="drawer-row"><span>GST (28%)</span><span>₹${Math.round(subtotal*0.28).toLocaleString('en-IN')}</span></div><div class="drawer-row-total"><span>Total</span><span>₹${Math.round(subtotal*1.28).toLocaleString('en-IN')}</span></div><a href="/checkout" data-link class="drawer-checkout-btn">CHECKOUT — ₹${Math.round(subtotal*1.28).toLocaleString('en-IN')}</a><button class="drawer-continue" data-close>Continue Shopping</button><p class="drawer-secure">🔒 Secure Checkout</p></div>`;}return `<div class="drawer-backdrop" data-close></div><aside class="drawer" id="drawer" aria-label="Shopping bag"><div class="drawer-head"><h2>Bag${count?` <span class="drawer-count">(${count})</span>`:''}</h2><button class="icon-btn" data-close aria-label="Close bag">×</button></div>${drawerInner}</aside><div class="modal-backdrop" data-modal-close></div><section class="modal" id="modal" role="dialog" aria-modal="true" aria-label="Quick view"></section><div class="toast" role="status" aria-live="polite"></div>`}
function bind(){document.querySelectorAll('[data-link]').forEach(a=>a.addEventListener('click',e=>{let href=a.getAttribute('href');if(href.startsWith('#'))return;e.preventDefault();history.pushState({},'',href);document.body.dataset.route=href;window.scrollTo(0,0);location.reload()}));document.querySelectorAll('[data-cart]').forEach(x=>x.onclick=openCart);document.querySelectorAll('[data-close]').forEach(x=>x.onclick=closeCart);document.querySelectorAll('[data-menu]').forEach(x=>x.onclick=()=>document.querySelector('#menu').classList.toggle('open'));document.querySelectorAll('[data-search]').forEach(x=>x.onclick=()=>{history.pushState({},'','/search');location.reload()});document.querySelectorAll('[data-wishlist]').forEach(x=>x.onclick=()=>{history.pushState({},'','/wishlist');location.reload()});document.querySelectorAll('[data-add]').forEach(x=>x.onclick=()=>add(x.dataset.add,Number(document.querySelector('#pdp-qty')?.textContent||1)));document.querySelectorAll('[data-wish]').forEach(x=>x.onclick=()=>wish(x.dataset.wish));document.querySelectorAll('[data-quick]').forEach(x=>x.onclick=()=>quick(x.dataset.quick));document.querySelectorAll('[data-cart-qty]').forEach(x=>x.onclick=()=>change(x.dataset.cartQty,+x.dataset.change));document.querySelectorAll('[data-remove]').forEach(x=>x.onclick=()=>remove(x.dataset.remove));document.querySelectorAll('[data-pdp-qty]').forEach(x=>x.onclick=()=>{let el=document.querySelector('#pdp-qty');el.textContent=Math.max(1,+el.textContent+(+x.dataset.pdpQty))});document.querySelectorAll('[data-feature]').forEach(x=>x.onclick=()=>feature(+x.dataset.feature));document.querySelectorAll('[data-mood]').forEach(x=>x.onclick=()=>mood(+x.dataset.mood));document.querySelectorAll('[data-slide]').forEach(x=>x.onclick=()=>showSlide(+x.dataset.slide,true));document.querySelector('[data-slide-next]')?.addEventListener('click',()=>showSlide(slide+1,true));document.querySelector('[data-slide-prev]')?.addEventListener('click',()=>showSlide(slide-1,true));document.querySelector('[data-sort]')?.addEventListener('change',e=>{let list=[...products];if(e.target.value==='az')list.sort((a,b)=>a.name.localeCompare(b.name));document.querySelector('#shop-grid').innerHTML=list.map(productCard).join('');bind()});document.querySelector('[data-search-input]')?.addEventListener('input',e=>updateSearch(e.target.value));document.querySelector('[data-contact]')?.addEventListener('submit',formSubmit);document.querySelector('[data-checkout]')?.addEventListener('submit',formSubmit);document.querySelector('[data-newsletter]')?.addEventListener('submit',e=>{e.preventDefault();e.target.reset();toast('Thank you for joining the season.')});}
function updateHeader(){document.querySelector('.header')?.replaceWith(document.createRange().createContextualFragment(header()).querySelector('.header'));}function add(slug,qty=1){let row=cart.find(i=>i.slug===slug);row?row.qty+=qty:cart.push({slug,qty});persist();render();toast('Added to your bag.');openCart();}function change(slug,n){let row=cart.find(i=>i.slug===slug);if(!row)return;row.qty+=n;if(row.qty<1)cart=cart.filter(i=>i.slug!==slug);persist();render()}function remove(slug){cart=cart.filter(i=>i.slug!==slug);persist();render()}function wish(slug){wishes=wishes.includes(slug)?wishes.filter(x=>x!==slug):[...wishes,slug];persist();render();toast(wishes.includes(slug)?'Saved to your wishlist.':'Removed from your wishlist.')}function openCart(){document.querySelector('.drawer').classList.add('open');document.querySelector('.drawer-backdrop').classList.add('open');document.body.classList.add('drawer-open')}function closeCart(){document.querySelector('.drawer').classList.remove('open');document.querySelector('.drawer-backdrop').classList.remove('open');document.body.classList.remove('drawer-open')}function quick(slug){let p=bySlug(slug),m=document.querySelector('#modal');m.innerHTML=`<button class="icon-btn" data-modal-close style="float:right">×</button><div class="quickview"><img src="${p.image}" alt="${p.name}"/><div><p class="eyebrow">${p.notes}</p><h2>${p.name}</h2><p>${p.description}</p><p>Extrait de Parfum · 50 ML</p><button class="btn" data-add="${p.slug}">Add to Bag</button></div></div>`;m.classList.add('open');document.querySelector('.modal-backdrop').classList.add('open');document.querySelectorAll('[data-modal-close]').forEach(x=>x.onclick=()=>{m.classList.remove('open');document.querySelector('.modal-backdrop').classList.remove('open')});m.querySelector('[data-add]').onclick=()=>add(p.slug)}function feature(i){let p=products[i],el=document.querySelector('#feature');el.querySelector('.feature-image img').src=p.image;el.querySelector('.feature-image img').alt=p.name;el.querySelector('.feature-no').textContent=`${String(i+1).padStart(2,'0')} — 06`;el.querySelector('.notes').textContent=p.notes;el.querySelector('h3').textContent=p.name;el.querySelector('h4').textContent=p.subtitle;el.querySelector('.feature-details>p:not(.notes)').textContent=p.description;el.querySelector('.text-link').href='/product/'+p.slug;el.querySelector('.text-link').textContent='Explore '+p.name;el.querySelectorAll('[data-feature]').forEach((x,n)=>x.classList.toggle('active',n===i))}function mood(i){activeMood=i;let p=products[i],el=document.querySelector('.mood-visual');el.querySelector('img').src=p.image;el.querySelector('img').alt=p.name;el.querySelector('h3').textContent=p.name;el.querySelector('p').textContent=p.character;document.querySelectorAll('[data-mood]').forEach((x,n)=>x.classList.toggle('active',n===i))}function showSlide(i){slide=(i+3)%3;document.querySelectorAll('.hero-slide').forEach((x,n)=>x.classList.toggle('active',n===slide));document.querySelectorAll('.dot').forEach((x,n)=>x.classList.toggle('active',n===slide))}function updateSearch(q){let term=q.toLowerCase();let results=products.filter(p=>[p.name,p.mood,p.notes,p.character].join(' ').toLowerCase().includes(term));document.querySelector('#search-results').innerHTML=results.length?results.map(productCard).join(''):empty('No fragrances found.','Explore all fragrances','/shop');bind()}function formSubmit(e){e.preventDefault();let valid=[...e.currentTarget.querySelectorAll('[required]')].every(i=>i.value.trim()&&i.checkValidity());let status=e.currentTarget.querySelector('.form-status');if(!valid){status.className='form-status error';status.textContent='Please complete the required fields.';return}status.className='form-status success';status.textContent='Thank you. Your message has been received.';e.currentTarget.reset()}function toast(msg){let t=document.querySelector('.toast');if(!t)return;t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2500)}
function showSlide(i,interacted=false){const slides=document.querySelectorAll('.banner-slide');if(!slides.length)return;if(interacted)heroPaused=true;slide=(i+slides.length)%slides.length;slides.forEach((x,n)=>x.classList.toggle('active',n===slide));document.querySelectorAll('.banner-dots button').forEach((x,n)=>x.classList.toggle('active',n===slide));}
function stage(i){const p=products[i],el=document.querySelector('#collection-stage');if(!el)return;el.style.setProperty('--stage',p.accent);el.querySelector('.stage-number').textContent=`${String(i+1).padStart(2,'0')} / 06`;el.querySelector('.notes').textContent=p.notes;el.querySelector('h2').textContent=p.name;el.querySelector('h3').textContent=p.subtitle;el.querySelector('.stage-description').textContent=p.description;el.querySelector('.stage-copy .text-link').href='/product/'+p.slug;el.querySelector('.stage-copy .text-link').textContent='Explore '+p.name;const image=el.querySelector('.stage-product img');image.style.opacity='0';setTimeout(()=>{image.src=p.image;image.alt=p.name;image.style.opacity='1'},160);el.querySelectorAll('[data-stage]').forEach((x,n)=>x.classList.toggle('active',n===i));}
function ritu(i){const p=products[i],el=document.querySelector('.ritu-product');if(!el)return;el.style.setProperty('--ritu',p.accent);const image=el.querySelector('img');image.style.opacity='0';setTimeout(()=>{image.src=p.image;image.alt=p.name;image.style.opacity='1'},150);el.querySelector('h3').textContent=p.name;el.querySelector('.ritu-caption>p:not(.eyebrow)').textContent=p.character;el.querySelector('.inline-link').href='/product/'+p.slug;document.querySelectorAll('[data-ritu]').forEach((x,n)=>x.classList.toggle('active',n===i));}
function setupMotion(){document.querySelectorAll('[data-stage]').forEach(x=>{const activate=()=>stage(+x.dataset.stage);x.onclick=activate;x.onmouseenter=activate;x.onfocus=activate});document.querySelectorAll('[data-ritu]').forEach(x=>{const activate=()=>ritu(+x.dataset.ritu);x.onclick=activate;x.onmouseenter=activate;x.onfocus=activate});let revealObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting)e.target.classList.add('is-visible')}),{threshold:.16});document.querySelectorAll('.reveal,.reveal-grid,.season-step').forEach(el=>revealObserver.observe(el));let seasonObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){document.querySelectorAll('.season-step').forEach(x=>x.classList.remove('active'));e.target.classList.add('active');if(+e.target.dataset.season===5)document.querySelector('.season-final-v2')?.classList.add('show')}}),{threshold:.75});document.querySelectorAll('.season-step').forEach(el=>seasonObserver.observe(el));const hero=document.querySelector('.banner-hero');if(hero){let startX=0;hero.addEventListener('touchstart',e=>startX=e.changedTouches[0].screenX,{passive:true});hero.addEventListener('touchend',e=>{let d=e.changedTouches[0].screenX-startX;if(Math.abs(d)>42)showSlide(slide+(d<0?1:-1),true)},{passive:true});hero.tabIndex=0;hero.addEventListener('keydown',e=>{if(e.key==='ArrowRight')showSlide(slide+1,true);if(e.key==='ArrowLeft')showSlide(slide-1,true)})}if(route==='/'&&!sessionStorage.getItem('tsr-loader'))bootLoader();setupScrollReveal();setupCarousel();setupReviewForm();setupFooterAccordions();}
function setupScrollReveal(){if(window.matchMedia('(prefers-reduced-motion:reduce)').matches)return;const srObserver=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('sr-visible');srObserver.unobserve(e.target)}})},{threshold:0.12,rootMargin:'0px 0px -40px 0px'});document.querySelectorAll('.sr,.sr-left,.sr-right,.sr-scale,.sr-stagger').forEach(el=>srObserver.observe(el))}
function setupV3Motion(){const header=document.querySelector('.header-v3');const announce=document.querySelector('.announce-v3');if(header&&document.querySelector('.home-v3')){header.classList.add('header-glass');if(announce)announce.style.display='none';const scrollFn=()=>header.classList.toggle('is-scrolled',window.scrollY>80);window.addEventListener('scroll',scrollFn,{passive:true});scrollFn()}const seasonMap=[{slug:'crystal-bloom'},{slug:'golden-ritual'},{slug:'dark-monsoon'},{slug:'flora-silk'},{slug:'golden-leaf'},{slug:'royal-zafran-rose'}];document.querySelectorAll('[data-v3-season]').forEach(el=>{const activate=()=>{const i=+el.dataset.v3Season;const p=bySlug(seasonMap[i].slug);const reveal=document.getElementById('v3-season-fragrance');if(!reveal||!p)return;document.querySelectorAll('[data-v3-season]').forEach((x,n)=>x.classList.toggle('active',n===i));const img=reveal.querySelector('img');img.style.opacity='0';setTimeout(()=>{img.src=p.image;img.alt=p.name;img.style.opacity='1'},150);reveal.querySelector('h4').textContent=p.name;reveal.querySelector('p').textContent=p.description;reveal.querySelector('.v3-link').href='/product/'+p.slug};el.onclick=activate;el.onmouseenter=activate});if(!window.matchMedia('(prefers-reduced-motion:reduce)').matches){const obs=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('v3-visible');obs.unobserve(e.target)}})},{threshold:0.1,rootMargin:'0px 0px -30px 0px'});document.querySelectorAll('.v3-sr').forEach(el=>obs.observe(el))}else{document.querySelectorAll('.v3-sr').forEach(el=>el.classList.add('v3-visible'))}if(window.matchMedia('(max-width:640px)').matches){document.querySelectorAll('.v3-footer [data-footer-toggle]').forEach(h4=>{const col=h4.closest('.footer-col');if(!col)return;const body=col.querySelector('.footer-col-body');if(!body)return;body.style.maxHeight='0';body.style.overflow='hidden';body.style.transition='max-height .3s ease';h4.onclick=()=>{const open=col.classList.toggle('open');body.style.maxHeight=open?body.scrollHeight+'px':'0'}})}document.querySelectorAll('a[href^="#"]').forEach(a=>{a.onclick=e=>{const target=document.querySelector(a.getAttribute('href'));if(target){e.preventDefault();target.scrollIntoView({behavior:'smooth',block:'start'})}}})}
function setupCarousel(){const track=document.getElementById('product-carousel');if(!track)return;const cards=[...track.children];if(!cards.length)return;let pos=0,dragging=false,startX=0,currentX=0,autoId=null;const gap=parseFloat(getComputedStyle(track).gap)||32;function cardW(){return cards[0].offsetWidth+gap}function maxPos(){return Math.max(0,(cards.length*cardW())-track.parentElement.offsetWidth)}function go(x,smooth=true){pos=Math.max(0,Math.min(x,maxPos()));track.style.transition=smooth?'transform .45s cubic-bezier(.22,1,.36,1)':'none';track.style.transform=`translateX(${-pos}px)`}function next(){go(pos+cardW())}function prev(){go(pos-cardW())}function startAuto(){stopAuto();autoId=setInterval(()=>{if(pos>=maxPos())go(0);else next()},3500)}function stopAuto(){if(autoId){clearInterval(autoId);autoId=null}}document.querySelector('[data-carousel-next]')?.addEventListener('click',()=>{stopAuto();next();startAuto()});document.querySelector('[data-carousel-prev]')?.addEventListener('click',()=>{stopAuto();prev();startAuto()});track.addEventListener('mousedown',e=>{dragging=true;startX=e.pageX;currentX=pos;track.classList.add('is-dragging');stopAuto()});window.addEventListener('mousemove',e=>{if(!dragging)return;go(currentX-(e.pageX-startX),false)});window.addEventListener('mouseup',()=>{if(!dragging)return;dragging=false;track.classList.remove('is-dragging');const nearest=Math.round(pos/cardW())*cardW();go(nearest);startAuto()});track.addEventListener('touchstart',e=>{startX=e.touches[0].pageX;currentX=pos;stopAuto()},{passive:true});track.addEventListener('touchmove',e=>{go(currentX-(e.touches[0].pageX-startX),false)},{passive:true});track.addEventListener('touchend',()=>{const nearest=Math.round(pos/cardW())*cardW();go(nearest);startAuto()},{passive:true});startAuto()}
function setupReviewForm(){const btn=document.querySelector('[data-write-review]');const form=document.getElementById('review-form');if(!btn||!form)return;btn.onclick=()=>{form.style.display=form.style.display==='none'?'block':'none';btn.textContent=form.style.display==='none'?'Write a Review':'Cancel'};form.querySelectorAll('[data-star]').forEach(s=>{s.onclick=()=>{const v=+s.dataset.star;form.querySelectorAll('[data-star]').forEach((x,i)=>x.textContent=i<v?'★':'☆');form.dataset.rating=v}});form.querySelector('[data-review-form]')?.addEventListener('submit',e=>{e.preventDefault();toast('Thank you for your review!');form.style.display='none';btn.textContent='Write a Review'})}
function setupPDP(){const zoomEl=document.querySelector('[data-pdp-zoom]');if(zoomEl){const lb=document.createElement('div');lb.className='pdp-lightbox';lb.innerHTML=`<button class="pdp-lightbox-close" aria-label="Close">×</button><img src="${zoomEl.querySelector('img').src}" alt="Zoomed view"/>`;document.body.appendChild(lb);zoomEl.onclick=()=>lb.classList.add('open');lb.onclick=()=>lb.classList.remove('open');lb.querySelector('.pdp-lightbox-close').onclick=e=>{e.stopPropagation();lb.classList.remove('open')};}document.querySelectorAll('[data-pdp-acc]').forEach(btn=>{btn.onclick=()=>{btn.closest('.pdp-acc').classList.toggle('open')}});const shareBtn=document.querySelector('[data-pdp-share]');const sharePop=document.querySelector('[data-share-pop]');if(shareBtn&&sharePop){shareBtn.onclick=e=>{e.stopPropagation();sharePop.style.display=sharePop.style.display==='none'?'block':'none'};document.addEventListener('click',e=>{if(!shareBtn.contains(e.target)&&!sharePop.contains(e.target))sharePop.style.display='none'});}document.querySelector('[data-share-copy]')?.addEventListener('click',()=>{navigator.clipboard?.writeText(location.href).then(()=>toast('Link copied!'));if(sharePop)sharePop.style.display='none'});document.querySelector('[data-scroll-reviews]')?.addEventListener('click',()=>{document.getElementById('reviews-section')?.scrollIntoView({behavior:'smooth'})});const rvBackdrop=document.querySelector('[data-rv-backdrop]');const rvModal=document.querySelector('[data-rv-modal]');if(rvBackdrop&&rvModal){const openRv=()=>{rvBackdrop.classList.add('open');rvModal.classList.add('open')};const closeRv=()=>{rvBackdrop.classList.remove('open');rvModal.classList.remove('open')};document.querySelector('[data-open-review-modal]')?.addEventListener('click',openRv);document.querySelector('[data-rv-modal-close]')?.addEventListener('click',closeRv);rvBackdrop.onclick=closeRv;let selRating=0;document.querySelectorAll('[data-rv-star]').forEach(btn=>{btn.onclick=e=>{e.preventDefault();selRating=+btn.dataset.rvStar;document.querySelectorAll('[data-rv-star]').forEach((b,i)=>{b.textContent=i<selRating?'★':'☆';b.classList.toggle('active',i<selRating)})}});document.querySelector('[data-rv-form]')?.addEventListener('submit',e=>{e.preventDefault();if(!selRating){toast('Please select a rating');return}toast('Thank you for your review!');closeRv();e.target.reset();selRating=0;document.querySelectorAll('[data-rv-star]').forEach(b=>{b.textContent='☆';b.classList.remove('active')})});}document.querySelector('[data-rv-sort]')?.addEventListener('change',e=>{const slug=route.split('/').pop();const pr=[...(reviews[slug]||[])];if(e.target.value==='highest')pr.sort((a,b)=>b.rating-a.rating);else if(e.target.value==='lowest')pr.sort((a,b)=>a.rating-b.rating);const grid=document.querySelector('[data-rv-grid]');const showing=+(grid?.dataset.showing||4);if(grid){grid.innerHTML=pr.slice(0,showing).map(r=>`<div class="rv-card"><div class="rv-card-stars">${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)}</div><p class="rv-card-text">${r.text}</p><div class="rv-card-meta"><span class="rv-card-author">${r.name}</span><span class="rv-card-date">${r.date}</span>${r.verified?'<span class="rv-card-verified">✓ Verified</span>':''}</div></div>`).join('')}});document.querySelector('[data-rv-more]')?.addEventListener('click',function(){const slug=route.split('/').pop();const pr=reviews[slug]||[];const grid=document.querySelector('[data-rv-grid]');if(grid){grid.dataset.showing=pr.length;grid.innerHTML=pr.map(r=>`<div class="rv-card"><div class="rv-card-stars">${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)}</div><p class="rv-card-text">${r.text}</p><div class="rv-card-meta"><span class="rv-card-author">${r.name}</span><span class="rv-card-date">${r.date}</span>${r.verified?'<span class="rv-card-verified">✓ Verified</span>':''}</div></div>`).join('');this.style.display='none'}});const stickyBar=document.querySelector('[data-pdp-sticky]');const addBtnEl=document.querySelector('[data-pdp-add]');if(stickyBar&&addBtnEl&&window.matchMedia('(max-width:768px)').matches){const obs=new IntersectionObserver(entries=>{entries.forEach(e=>{stickyBar.classList.toggle('visible',!e.isIntersecting)})},{threshold:0});obs.observe(addBtnEl);}document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelector('.pdp-lightbox')?.classList.remove('open');document.querySelector('[data-rv-backdrop]')?.classList.remove('open');document.querySelector('[data-rv-modal]')?.classList.remove('open');closeCart()}});}

