function setupFooterAccordions(){if(window.matchMedia('(min-width:641px)').matches)return;document.querySelectorAll('[data-footer-toggle]').forEach(h3=>{const col=h3.closest('[data-footer-col]');if(!col)return;const body=col.querySelector('.footer-col-body');if(!body)return;body.style.maxHeight='0';body.style.overflow='hidden';body.style.transition='max-height .3s ease';h3.style.cursor='pointer';h3.onclick=()=>{const open=col.classList.toggle('open');body.style.maxHeight=open?body.scrollHeight+'px':'0';h3.querySelector('.footer-chevron').style.transform=open?'rotate(90deg)':''}})}
function bootLoader(){sessionStorage.setItem('tsr-loader','1');const loader=document.createElement('div');loader.className='loader-v2';loader.innerHTML='<img src="/logo.png" alt="The Sixth Ritu"/><span></span><strong>THE SIXTH RITU</strong><em>THE SEASON OF LUXURY</em>';document.body.append(loader);setTimeout(()=>loader.classList.add('exit'),1600);setTimeout(()=>loader.remove(),2100);}
function applyBannerSources(){const mobile=window.matchMedia('(max-width: 640px)').matches;document.querySelectorAll('.banner-slide').forEach(slideEl=>{const source=slideEl.querySelector('source');const image=slideEl.querySelector('img');if(!source||!image)return;if(!image.dataset.desktop)image.dataset.desktop=image.getAttribute('src');source.media='not all';image.src=mobile?source.getAttribute('srcset'):image.dataset.desktop;});}
